@page "/recipes/{CuisineId:int}"
@rendermode InteractiveServer
@using sv_04fa95046569442a8d6ec5ff4b4b908a.Services
@using Microsoft.AspNetCore.Components
@implements IDisposable
@inject IRecipeService RecipeService
@inject ILogger<Recipes> Logger
@inject NavigationManager Navigation

<PageTitle>Recipes</PageTitle>

<h1>Recipes</h1>

@if (_error is not null)
{
    <div class="alert alert-danger" role="alert">
        <p>@_error</p>
        <button class="btn btn-outline-danger" @onclick="RetryAsync">Retry</button>
    </div>
}
else if (_recipes is null && _isLoading)
{
    <div class="loading-placeholder">
        <p><em>Loading recipes…</em></p>
    </div>
}
else
{
    @if (_isLoading)
    {
        <div class="refreshing-indicator">
            <small><em>Refreshing…</em></small>
        </div>
    }

    @if (_recipes is not null)
    {
        <div class="recipe-list">
            @foreach (var recipe in GetSortedRecipes())
            {
                <div class="recipe-card">
                    <h3>@recipe.Title</h3>
                    <p>@recipe.Description</p>
                    <small>Prep time: @recipe.PrepTimeMinutes minutes</small>
                </div>
            }
            @if (_recipes.Count == 0)
            {
                <p>No recipes found for this cuisine.</p>
            }
        </div>
    }
}

@code {
    [Parameter]
    public int CuisineId { get; set; }

    [SupplyParameterFromQuery(Name = "sort")]
    public string? Sort { get; set; }

    private List<Recipe>? _recipes;
    private bool _isLoading;
    private string? _error;
    private int _currentCuisineId;
    private CancellationTokenSource? _loadCts;

    protected override async Task OnParametersSetAsync()
    {
        if (CuisineId == _currentCuisineId)
        {
            // Only sort changed — no reload needed.
            return;
        }

        _currentCuisineId = CuisineId;
        await LoadRecipesAsync();
    }

    private async Task LoadRecipesAsync()
    {
        // Cancel any in-flight request.
        await CancelPendingLoadAsync();

        _error = null;
        _isLoading = true;
        StateHasChanged();

        var cts = new CancellationTokenSource();
        _loadCts = cts;

        try
        {
            var results = await RecipeService.GetByCuisineAsync(_currentCuisineId, cts.Token);
            if (cts.Token.IsCancellationRequested)
                return;

            _recipes = results;
            _error = null;
        }
        catch (OperationCanceledException)
        {
            // Request was intentionally cancelled — do nothing.
        }
        catch (TimeoutException ex)
        {
            Logger.LogError(ex, "Timeout loading recipes for cuisine {CuisineId}", _currentCuisineId);
            _error = "The request timed out. Please try again.";
        }
        catch (Exception ex)
        {
            Logger.LogError(ex, "Error loading recipes for cuisine {CuisineId}", _currentCuisineId);
            _error = "Something went wrong loading recipes. Please try again.";
        }
        finally
        {
            if (!cts.Token.IsCancellationRequested)
            {
                _isLoading = false;
            }
        }
    }

    private async Task RetryAsync()
    {
        await LoadRecipesAsync();
    }

    private List<Recipe> GetSortedRecipes()
    {
        if (_recipes is null)
            return new List<Recipe>();

        return Sort?.ToLowerInvariant() switch
        {
            "newest" => _recipes.OrderByDescending(r => r.Id).ToList(),
            "popular" => _recipes.OrderBy(r => r.PrepTimeMinutes).ToList(),
            _ => _recipes,
        };
    }

    private async Task CancelPendingLoadAsync()
    {
        if (_loadCts is not null)
        {
            await _loadCts.CancelAsync();
            _loadCts.Dispose();
            _loadCts = null;
        }
    }

    public void Dispose()
    {
        _loadCts?.Cancel();
        _loadCts?.Dispose();
        _loadCts = null;
    }
}

